INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('7ff2f903-f9df-58c6-a0c6-424564880ce1','b8330080-2c08-584f-87b6-7c6c8f8a3b93','Decreto de publicación','<h1> DECRETO por el que se expide la Ley de Ingresos de la Federación para el Ejercicio Fiscal de 2027.</h1>
