INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('b9cffbf4-8a6d-58c9-bba3-0e6f3462d58b','45b525f1-e91c-52b5-b345-68403c4d5c07','Nota editorial · Reforma de noviembre de 2026','<p>Publicación original de la Ley del Impuesto sobre la Renta. Consulta el decreto de reforma del 13 de noviembre de 2026 y sus disposiciones en el acervo.</p><p><a href="#ley-b3993e78-5dce-5feb-bfe1-918ccb7fa807">Reforma publicada el 13 de noviembre de 2026</a></p>','1','complementario');
