INSERT INTO public.leyes (id,titulo,siglas,fecha_publicacion,url_original,tipo,vigente) VALUES ('b3993e78-5dce-5feb-bfe1-918ccb7fa807','DECRETO por el que se reforman, adicionan y derogan diversas disposiciones de la Ley del Impuesto sobre la Renta y se expiden disposiciones de vigencia transitoria.','REF-LISR-2026','2026-11-13','https://sidof.segob.gob.mx/notas/5803758','decreto',NULL);
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('631be357-1851-5205-abc5-2300a1db882a','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Decreto de publicación','<h1> DECRETO por el que se reforman, adicionan y derogan diversas disposiciones de la Ley del Impuesto sobre la Renta y se expiden disposiciones de vigencia transitoria.</h1>
<h2> Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República.</h2>
<div> CLAUDIA SHEINBAUM PARDO, Presidenta de los Estados Unidos Mexicanos, a sus habitantes sabed:</div>
<div> Que el Honorable Congreso de la Unión, se ha servido dirigirme el siguiente</div>
<div> DECRETO<br/> </div>
<div> "EL CONGRESO GENERAL DE LOS ESTADOS UNIDOS MEXICANOS, D E C R E T A :</div>
<div> SE REFORMAN, ADICIONAN Y DEROGAN DIVERSAS DISPOSICIONES DE LA LEY DEL IMPUESTO SOBRE LA RENTA Y SE EXPIDEN DISPOSICIONES DE VIGENCIA TRANSITORIA</div>
<div> LEY DEL IMPUESTO SOBRE LA RENTA<br/> </div>','1','preambulo');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('0779ccd4-d9df-54db-8e44-159d5d2132ab','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo Primero','<div> Artículo Primero.- Se reforman los artículos 22, párrafo noveno; 27, fracciones V, párrafo primero y XVIII, párrafo segundo; 28, fracción XXXII, párrafo primero; 77, párrafo tercero, fracción II, y párrafo quinto; 78, párrafos décimo primero y décimo séptimo; 113-E, párrafos primero, tercero, quinto, TABLA MENSUAL, séptimo y noveno; 113-F, párrafo primero, TABLA ANUAL; 113-H, fracción II; 147, fracción VII, párrafo primero; 153, párrafo quinto; 206, párrafos primero y tercero, fracciones III y V; 209, párrafo segundo, apartados A, fracciones I, II y III, B, fracciones I, incisos a) y b), II, incisos a), b), c), d) y e), III, IV, V, incisos a) y b), VI, VII, VIII, X, incisos a), b), c), d) y e), XI, incisos a) y b), y XIV y C, fracciones I, II, III, IV, V, VI, VII, VIII, IX, X, XI, XII, XIII y XIV y 214, párrafo primero; se adicionan a los artículos 22, párrafo primero, fracción II, inciso a), párrafos tercero y cuarto; 25, párrafo tercero; 27, fracción XVIII, párrafo cuarto, y 206, párrafo cuarto, así como el Capítulo X "Del Mecanismo de Control de las Deducciones Autorizadas y de las Pérdidas Fiscales" al Título II, que comprende los artículos 78-A, 78-B, 78-C, 78-D, 78-E y 78-F, y se derogan los artículos 36, fracción III, párrafo cuarto y 74, párrafo segundo, así como el Capítulo VI del Título II, que comprende los artículos del 59, 60, 61, 62, 63, 64, 65, 66, 67, 68, 69, 70 y 71, de la Ley del Impuesto sobre la Renta, para quedar como sigue:</div>','2','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('e71eacd6-6095-5a4d-8210-3915ea32e084','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 22','<div> Artículo 22. ...</div>
<div> I.          ...</div>
<div> II.         ...</div>
<div> a)    ...</div>
<div>        ...</div>
<div>        Los intereses devengados no pagados y el impuesto al valor agregado correspondientes a pasivos capitalizados no formarán parte del costo comprobado de adquisición de las acciones.</div>
<div>        Tratándose de aportaciones en especie consistentes en cuentas por cobrar, cesión de derechos de cobro o de títulos de crédito, estas se adicionarán al costo comprobado de adquisición hasta el momento en que se materialicen y hasta por el importe que se cobre en efectivo.</div>
<div> b)    ...</div>
<div> III. y IV.  ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> Cuando en este artículo se haga referencia a reembolsos pagados, se entenderán incluidas las amortizaciones de pérdidas y las reducciones de capital a que se refiere el artículo 78 del presente ordenamiento. En estos casos, los contribuyentes únicamente considerarán las amortizaciones, reembolsos o reducciones de capital, que les correspondan a las acciones que no se hayan cancelado, con motivo de dichas operaciones.</div>
<div> ...</div>','3','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('43732caa-9643-54cd-b857-e549b51e3a34','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 25','<div> Artículo 25. ...</div>
<div> I. a X.    ...</div>
<div> ...</div>
<div> Tratándose de anticipos por la prestación de servicios y el otorgamiento del uso o goce temporal de bienes, la deducción procederá únicamente en el ejercicio en que se preste el servicio o transcurra el periodo de uso o goce correspondiente. Cuando la prestación de servicios o el otorgamiento del uso o goce temporal de bienes comprenda más de un ejercicio fiscal, la deducción procederá solo en la parte efectivamente recibida u otorgada.</div>','4','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('f0292124-07f7-5b3c-a629-75bb9b8f65e4','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 27','<div> Artículo 27. ...</div>
<div> I. a IV.   ...</div>
<div> V.         Cumplir con las obligaciones establecidas en esta Ley y las demás disposiciones fiscales en materia de retención y entero de impuestos a cargo de terceros o que, en su caso, se recabe de éstos copia de los documentos en que conste el pago de dichos impuestos. Tratándose de pagos al extranjero, éstos sólo se podrán deducir en el ejercicio en el que se pague la contraprestación y se entere la retención que corresponda en términos del artículo 153, quinto párrafo, de esta Ley y siempre que el contribuyente proporcione la información a que esté obligado en los términos del artículo 76 de esta Ley.</div>
<div>             ...</div>
<div>             ...</div>
<div> VI. a XVII. ...</div>
<div> XVIII.     ...</div>
<div>             Tratándose de anticipos por los gastos a que se refiere la fracción III del artículo 25 de esta Ley, estos serán deducibles en el ejercicio en el que se efectúen, siempre que se cuente con el comprobante fiscal del anticipo en el mismo ejercicio en el que se pagó y con el comprobante fiscal que ampare la totalidad de la operación por la que se efectuó el anticipo, a más tardar el último día del ejercicio siguiente a aquel en que se dio el anticipo. La deducción del anticipo en el ejercicio en el que se pague será por el monto de este y, en el ejercicio en el que se reciba el bien, la deducción será por la diferencia entre el valor total consignado en el comprobante fiscal y el monto del anticipo. En todo caso para efectuar esta deducción, se deberán cumplir con los demás requisitos que establezcan las disposiciones fiscales.</div>
<div>             ...</div>
<div>             Lo establecido en esta fracción no será aplicable a los anticipos a que se refiere el artículo 25, párrafo tercero, de la presente Ley, sin perjuicio de la obligación consistente en contar con el comprobante fiscal en el mismo ejercicio en el que se pagaron y con el comprobante fiscal que ampare la totalidad de la operación por la que se efectuaron.</div>
<div> XIX. a XXII. ...</div>','5','ordinario');
