INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('21dd91cd-a153-5ffe-bf02-73704ee30dad','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 77','<div> Artículo 77. ...</div>
<div> ...</div>
<div> ...</div>
<div> I.          ...</div>
<div> II.         El importe de las partidas no deducibles para efectos del impuesto sobre la renta, excepto las señaladas en el artículo 28, fracciones VIII y IX de esta Ley y la participación de los trabajadores en las utilidades de las empresas a que se refiere el artículo 9, fracción I, de este ordenamiento, así como aquellas que no cumplan con los requisitos fiscales previstos en las disposiciones aplicables.</div>
<div> III.        ...</div>
<div> ...</div>
<div> Cuando la suma del impuesto sobre la renta pagado en los términos del artículo 9 de esta Ley, las partidas no deducibles para efectos del impuesto sobre la renta, excepto las señaladas en las fracciones VIII y IX del artículo 28 de esta Ley, la participación de los trabajadores en las utilidades de las empresas a que se refiere la fracción I del artículo 9 de este ordenamiento, y el monto que se determine conforme al párrafo anterior; así como aquellas que no cumplan con los requisitos fiscales previstos en las disposiciones aplicables, sea mayor al resultado fiscal del ejercicio, la diferencia se disminuirá del saldo de la cuenta de utilidad fiscal neta que se tenga al final del ejercicio o, en su caso, de la utilidad fiscal neta que se determine en los siguientes ejercicios, hasta agotarlo. En este último caso, el monto que se disminuya se actualizará desde el último mes del ejercicio en el que se determinó y hasta el último mes del ejercicio en el que se disminuya.</div>
<div> ...</div>
<div> ...</div>','23','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('1fa903a6-7af3-537d-a55a-04e0c9a564c6','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 78','<div> Artículo 78. ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> Para determinar el capital de aportación actualizado, las personas morales llevarán una cuenta de capital de aportación que se adicionará con las aportaciones de capital, las primas netas por suscripción de acciones efectuadas por los socios o accionistas, y se disminuirá con las reducciones de capital que se efectúen. Para los efectos de este párrafo, no se incluirá como capital de aportación, el correspondiente a la reinversión o capitalización de utilidades o de cualquier otro concepto que conforme el capital contable de la persona moral ni el proveniente de reinversiones de dividendos o utilidades en aumento de capital de las personas que los distribuyan realizadas dentro de los treinta días siguientes a su distribución. Tratándose de la capitalización de pasivos, no se incluirán como capital de aportación los intereses devengados no pagados, así como el impuesto al valor agregado correspondiente a dichos pasivos; en el caso de aportaciones en especie conformadas por cuentas por cobrar, cesión de derechos de cobro o de títulos de crédito, estas se adicionarán hasta el momento en que se materialicen y hasta por el importe que se cobre en efectivo. Los conceptos correspondientes a aumentos de capital mencionados en este párrafo, se adicionarán a la cuenta de capital de aportación en el momento en el que se paguen efectivamente, los cuales deberán contar con la documentación soporte conforme al Código Fiscal de la Federación, y los conceptos relativos a reducciones de capital se disminuirán de la citada cuenta en el momento en el que se pague el reembolso o se efectúe la reducción de capital, según sea el caso.</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>
<div> Lo dispuesto en este artículo será aplicable, indistintamente, al reembolso, a la amortización de pérdidas o a la reducción de capital, independientemente de que haya o no cancelación de acciones.</div>
<div> ...</div>','24','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('13cbf423-056d-5db0-91b8-e41104bd318d','b3993e78-5dce-5feb-bfe1-918ccb7fa807','CAPÍTULO X','<div> CAPÍTULO X<br/> </div>
<div> DEL MECANISMO DE CONTROL DE LAS DEDUCCIONES AUTORIZADAS Y DE LAS PÉRDIDAS FISCALES<br/> </div>','25','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('11b1aaee-3ba8-546d-8259-91e555ed22ec','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 78-A','<div> Artículo 78-A. Para efectos del artículo 9 de esta Ley, las personas morales residentes en México que obtengan ingresos acumulables de los señalados en este Título superiores a 50 millones de pesos y determinen utilidad fiscal del ejercicio en términos del citado artículo 9, aplicarán en el ejercicio de que se trate, sus deducciones autorizadas y pérdidas fiscales a que se refiere este Título, conforme a los límites que se establecen en el presente Capítulo.</div>
<div> La renta gravable para efectos de la participación de los trabajadores en las utilidades de las empresas se determinará conforme a lo establecido en el artículo 9, párrafos cuarto y quinto, de esta Ley, sin considerar los límites establecidos en el presente Capítulo.</div>','26','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('a04c8a2f-8cba-567b-950f-a07f80948382','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 78-B','<div> Artículo 78-B. Para efectos del artículo 78-A de esta Ley, el límite de las deducciones autorizadas se determinará conforme a lo siguiente:</div>
<div> A.       Se aplicará el factor que corresponda conforme a lo siguiente:</div>
<div> I.        Cuando el total de las deducciones autorizadas a que se refiere este Título sea menor o igual al resultado que se obtenga de multiplicar los ingresos acumulables del ejercicio que corresponda por el factor de 0.9667, el límite de dichas deducciones autorizadas será el monto que se obtenga como resultado de multiplicar el total de las deducciones autorizadas a que se refiere este Título por el factor de 0.9900.</div>
<div> II.       Cuando el total de las deducciones autorizadas a que se refiere este Título sea mayor al resultado que se obtenga de multiplicar los ingresos acumulables del ejercicio que corresponda por el factor de 0.9667, el límite de las deducciones autorizadas será igual a este último resultado.</div>
<div> B.      Las deducciones autorizadas que no sean disminuidas de la totalidad de los ingresos acumulables obtenidos en el ejercicio como consecuencia de la aplicación del límite establecido en este artículo, podrán disminuirse en los veinte ejercicios siguientes hasta agotarlas, conforme a lo siguiente:</div>
<div> I.        En cada ejercicio, al resultado de sumar el monto de las deducciones de ejercicios anteriores no disminuidas en los términos de este artículo y las deducciones autorizadas del ejercicio que corresponda, se le aplicará el límite que corresponda conforme a lo establecido en el Apartado anterior.</div>
<div> II.       El monto de las deducciones no disminuidas en los términos de este artículo se actualizará multiplicándolo por el factor de actualización correspondiente al periodo comprendido desde el primer mes de la segunda mitad del ejercicio en que se generaron y hasta el último mes de dicho ejercicio. La parte de las deducciones pendientes de disminuir correspondientes a ejercicios anteriores, una vez actualizadas, se actualizará multiplicándola por el factor de actualización correspondiente al periodo comprendido desde el mes en el que se actualizó por última vez y hasta el último mes de la primera mitad del ejercicio en el que se disminuirán.</div>
<div>          Para los efectos del párrafo anterior, cuando el número de meses del ejercicio en que se generó la deducción sea impar, se considerará como primer mes de la segunda mitad, el mes inmediato posterior al que corresponda la mitad del ejercicio.</div>
<div> III.      Cuando el contribuyente no disminuya en un ejercicio las deducciones determinadas conforme a este Apartado, pudiendo haberlo efectuado conforme a lo establecido en este artículo, perderá el derecho a hacerlo en los ejercicios posteriores, hasta por la cantidad que no estuvo sujeta al límite establecido en el presente artículo.</div>
<div> El derecho a disminuir las deducciones es personal del contribuyente que las haya generado y no podrá transmitirse a otra persona ni como consecuencia de fusión o escisión.</div>
<div> En ningún caso se podrán disminuir de la totalidad de los ingresos acumulables obtenidos en el ejercicio, deducciones que excedan el límite señalado en este artículo.</div>
<div> Las deducciones pendientes de disminuir en términos de este artículo no se considerarán pérdida fiscal para efectos del artículo 57 de esta Ley.</div>','27','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('4557a63d-83df-5324-9b2d-fb6540a05c61','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 78-C','<div> Artículo 78-C. Para efectos del artículo 78-A de esta Ley, el límite de las pérdidas fiscales pendientes de aplicar de ejercicios anteriores que se podrá disminuir de la utilidad fiscal del ejercicio, será el monto que se obtenga como resultado de multiplicar la utilidad fiscal del ejercicio, después de aplicar el límite a las deducciones que establece el artículo 78-B de esta Ley, por el factor de 0.5000. Cuando las pérdidas fiscales pendientes de aplicar de ejercicios anteriores sean inferiores al resultado obtenido en términos de este párrafo únicamente se podrán disminuir dichas pérdidas.</div>
<div> Las pérdidas fiscales que no sean disminuidas de la utilidad fiscal del ejercicio, debido a la aplicación de la metodología establecida en este artículo, podrán disminuirse en los veinte ejercicios siguientes hasta agotarlas, en términos del artículo 57 de esta Ley, aplicando a estas el límite establecido en el presente artículo.</div>','28','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('e5cb3ba5-e885-5900-9462-516bc5c854b4','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 78-D','<div> Artículo 78-D. Para los efectos del artículo 14, fracción II, inciso c), de esta Ley, las personas morales residentes en México que en el ejercicio inmediato anterior hayan obtenido ingresos acumulables de los señalados en este Título superiores a 50 millones de pesos, que cuenten con pérdida fiscal de ejercicios anteriores pendiente de disminuir de las utilidades fiscales, sólo podrán disminuir por concepto de dicha pérdida fiscal el monto que se obtenga como resultado de multiplicar la utilidad fiscal para el pago provisional determinada en términos del artículo 14, fracción II, incisos a) y b), de esta Ley, por el factor de 0.5000. Cuando la pérdida fiscal de ejercicios anteriores pendiente de aplicar contra las utilidades fiscales sea inferior al resultado obtenido en términos de este párrafo, únicamente se podrá disminuir dicha pérdida.</div>','29','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('8272d753-6b64-5a41-9f6d-66f01e3e8fbe','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 78-E','<div> Artículo 78-E. No aplicarán lo dispuesto en este Capítulo los siguientes contribuyentes:</div>
<div> I.        Que tributen en el régimen de Coordinados establecido en el Título II, Capítulo VII, de esta Ley.</div>
<div> II.       Que tributen en el régimen de Actividades Agrícolas, Ganaderas, Silvícolas y Pesqueras establecido en el Título II, Capítulo VIII, de esta Ley.</div>
<div> III.      Que lleven a cabo operaciones de maquila en términos del artículo 182 de esta Ley, así como aquellos que realicen operaciones al amparo de una autorización de establecimiento de depósito fiscal para el ensamble y fabricación de vehículos conforme al artículo 121, fracción IV de la Ley Aduanera; salvo por los ingresos que se obtengan por la enajenación de mercancías en territorio nacional.</div>
<div> IV.      Que sean declarados en quiebra en términos de la Ley de Concursos Mercantiles.</div>
<div> V.       Que apliquen los beneficios fiscales consistentes en la deducción inmediata de inversiones o la deducción adicional de gastos de capacitación, certificaciones iniciales, modelos de utilidad y obtención de patentes, incluidos aquellos en los que se requiera autorización o una constancia de cumplimiento para su aplicación, durante la vigencia del beneficio otorgado y exclusivamente respecto a dicho beneficio.</div>
<div> VI.      Que en el ejercicio de que se trate tengan menos de cinco ejercicios fiscales de haber obtenido su inscripción en el Registro Federal de Contribuyentes.</div>
<div>          No será aplicable lo establecido en esta fracción a los contribuyentes que de una persona moral preexistente reciban, adquieran o por cualquier medio utilicen activos, inventarios, derechos, contratos, concesiones, marcas, cartera de clientes o cualquier otro bien indispensable para realizar actividades económicas similares a la de dicha persona moral y cuenten con los mismos socios, accionistas o integrantes o que los socios, accionistas o integrantes de la referida persona moral mantengan, directa o indirectamente, el control o la administración de la que recibe, adquiere o utilice los citados elementos.</div>
<div>          Las autoridades fiscales podrán, como resultado del ejercicio de sus facultades de comprobación, determinar que no resulta aplicable la excepción establecida en esta fracción cuando los contribuyentes lleven a cabo la constitución, fusión, escisión, liquidación o reestructuración de sociedades, venta de acciones o partes sociales o cualquier otro movimiento corporativo, con la finalidad de aplicar la excepción establecida en el párrafo primero de esta fracción.</div>
<div> VII.     Que se trate de sociedades que subsistan o surjan con motivo de la fusión de dos o más sociedades o la escisión de una sociedad, que se encuentren dentro de los cinco ejercicios fiscales a que se refiere la fracción VI de este artículo.</div>
<div>          La excepción establecida en esta fracción sólo se aplicará a las sociedades que subsistan o surjan por el plazo que le restaba cumplir a la sociedad escindente o a la sociedad fusionante o fusionada que mayor tiempo tenía de creada.</div>
<div> VIII.    Las instituciones de seguros en la realización de las operaciones propias de su objeto.</div>
<div> IX.      Que realicen la actividad de expendio al público, distribución o comercialización de gasolinas y diésel, que cuenten con el permiso correspondiente a que se refiere el artículo 76, fracción II, inciso b) de la Ley del Sector Hidrocarburos.</div>','30','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('a0aadd92-daf4-5b2e-a162-1a85b81dc2ae','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 78-F','<div> Artículo 78-F. El Servicio de Administración Tributaria queda facultado para emitir las reglas de carácter general que resulten necesarias para la debida aplicación de lo establecido en este Capítulo.</div>','31','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('c951e194-1f3d-5acc-91f3-be7f8da152d7','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 113-E','<div> Artículo 113-E. Los contribuyentes personas físicas que realicen únicamente actividades empresariales, profesionales u otorguen el uso o goce temporal de bienes, podrán optar por pagar el impuesto sobre la renta en los términos establecidos en esta Sección, siempre que la totalidad de sus ingresos propios de la actividad o las actividades señaladas que realicen, obtenidos en el ejercicio inmediato anterior, no hubieran excedido de la cantidad de cinco millones de pesos.</div>
<div> ...</div>
<div> Para los efectos de los párrafos anteriores, en caso de que los ingresos a que se refiere este artículo excedan de cinco millones de pesos en cualquier momento del año de tributación, o se incumpla con alguna de las obligaciones a que se refiere el artículo 113-G de esta Ley, o se actualice el supuesto previsto en el artículo 113-I de la misma Ley relativo a las declaraciones, no les serán aplicables a los contribuyentes las disposiciones de esta Sección, debiendo pagar el impuesto respectivo de conformidad con las disposiciones del Título IV, Capítulo II, Sección I o Capítulo III de esta Ley, según corresponda, a partir del mes siguiente a la fecha en que tales ingresos excedan la referida cantidad y los pagos efectuados en los meses transcurridos se considerarán pagos definitivos. En su caso, las autoridades fiscales podrán asignar al contribuyente el régimen que le corresponda, sin que medie solicitud del contribuyente.</div>
<div> ...</div>
<div> ...</div>
<div> TABLA MENSUAL<br/> </div>
<table>       <thead><tr> <th> <div> Monto de los ingresos amparados por comprobantes fiscales efectivamente cobrados, sin impuesto al valor agregado (pesos mensuales)</div> </th> <th> <div> Tasa aplicable<br/> </div> </th> </tr></thead><tbody><tr> <td> <div> Hasta 25,000.00</div> </td> <td> <div> 1.00%<br/> </div> </td> </tr><tr> <td> <div> Hasta 50,000.00</div> </td> <td> <div> 1.10%<br/> </div> </td> </tr><tr> <td> <div> Hasta 83,333.33</div> </td> <td> <div> 1.50%<br/> </div> </td> </tr><tr> <td> <div> Hasta 208,333.33</div> </td> <td> <div> 2.00%<br/> </div> </td> </tr><tr> <td> <div> Hasta 5,000,000.00</div> </td> <td> <div> 2.50%<br/> </div> </td> </tr></tbody></table>
<div> ...</div>
<div> Los contribuyentes que dejen de tributar conforme a esta Sección, podrán volver a tributar a partir del ejercicio fiscal siguiente, conforme a la misma, siempre que los ingresos obtenidos en el ejercicio inmediato anterior a aquel de que se trate, no excedan de cinco millones de pesos y se encuentren al corriente en el cumplimiento de sus obligaciones fiscales.</div>
<div> ...</div>
<div> Las personas físicas que se dediquen exclusivamente a las actividades agrícolas, ganaderas, silvícolas o pesqueras, cuyos ingresos en el ejercicio no excedan de un millón de pesos efectivamente cobrados, no pagarán el impuesto sobre la renta por los ingresos provenientes de dichas actividades. En caso de que los referidos ingresos excedan dicho monto, a partir de la declaración mensual correspondiente se deberá pagar el impuesto conforme al Título IV, Capítulo II, Sección IV, de esta Ley, en los términos que se determine mediante reglas de carácter general que al efecto emita el Servicio de Administración Tributaria.</div>
<div> ...</div>','32','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('a70a0666-6db0-57c5-8258-c32e73e7acf0','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 113-F','<div> Artículo 113-F. ...</div>
<div> TABLA ANUAL<br/> </div>
