INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('380b03aa-10ad-5005-82d6-6f81518c25a2','b3993e78-5dce-5feb-bfe1-918ccb7fa807','Artículo 147','<div> Artículo 147. ...</div>
<div> I. a VI.   ...</div>
<div> VII.       Que se cumplan las obligaciones establecidas en esta Ley en materia de retención y entero de impuestos a cargo de terceros o que, en su caso, se recabe de éstos copia de los documentos en que conste el pago de dichos impuestos. Tratándose de pagos al extranjero, sólo se podrán deducir en el ejercicio en el que se pague la contraprestación y se entere la retención que corresponda en términos del artículo 153, quinto párrafo, de esta Ley y siempre que el contribuyente proporcione la información a que esté obligado en los términos del artículo 76, fracción VI de esta Ley.</div>
<div>             ...</div>
