INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('a0b4d4f9-0513-5f13-9555-e04b86032161','ecad609a-fdcb-5d6d-8de4-2bbb31a70d73','Nota editorial · Reforma de noviembre de 2026','<p>Publicación original de la Ley de Inversión Extranjera. Consulta el decreto de reforma del 19 de noviembre de 2026 y sus disposiciones en el acervo.</p><p><a href="#ley-33120acd-fa2a-5ee0-a2b5-7bfda197ed07">Reforma publicada el 19 de noviembre de 2026</a></p>','1','complementario');
