INSERT INTO public.leyes (id,titulo,siglas,fecha_publicacion,url_original,tipo,vigente) VALUES ('33120acd-fa2a-5ee0-a2b5-7bfda197ed07','DECRETO por el que se reforman, adicionan y derogan diversas disposiciones de la Ley de Inversión Extranjera.','REF-INVERSION-EXTRANJERA-2026','2026-11-19','https://sidof.segob.gob.mx/notas/5804310','decreto',NULL);
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('2e615ec5-23ca-5b58-8760-ff0f26092521','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Decreto de publicación','<h1> DECRETO por el que se reforman, adicionan y derogan diversas disposiciones de la Ley de Inversión Extranjera.</h1>
<h2> Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República.</h2>
<div> CLAUDIA SHEINBAUM PARDO, Presidenta de los Estados Unidos Mexicanos, a sus habitantes sabed:</div>
<div> Que el Honorable Congreso de la Unión, se ha servido dirigirme el siguiente</div>
<div> DECRETO<br/> </div>
<div> "EL CONGRESO GENERAL DE LOS ESTADOS UNIDOS MEXICANOS, D E C R E T A :</div>
<div> SE REFORMAN, ADICIONAN Y DEROGAN DIVERSAS DISPOSICIONES DE LA LEY DE INVERSIÓN EXTRANJERA</div>','1','preambulo');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('a0f84423-4f60-5c09-9bbd-ce7f6ad8b1a6','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo Único','<div> Artículo Único.- Se reforman los artículos 23, párrafo primero; 27, fracciones IV y actual V del párrafo primero; 28; 29, fracciones III y IV del párrafo primero; y 38, fracciones I, II, III, IV, V y actual VI del párrafo primero; se adicionan un tercer y cuarto párrafo al artículo 23; una fracción V recorriéndose en su orden la fracción subsecuente al párrafo primero del artículo 27; una fracción V del párrafo primero al artículo 29; un Título Sexto Bis, el cual comprende los Capítulos I, con su artículo 30 Bis, y II, con sus artículos 30 Ter, 30 Quater, 30 Quinquies y 30 Sexies; unas fracciones VI y VII recorriéndose en su orden la fracción subsecuente al párrafo primero y un segundo y tercer párrafo al artículo 38; y se derogan el artículo 30 y el actual párrafo segundo del artículo 38, de la Ley de Inversión Extranjera, para quedar como sigue:</div>','2','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('19096f5e-0058-5ce9-9fd8-26ac87f3487b','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 23','<div> ARTÍCULO 23.- La Comisión se integra por las personas titulares de las secretarías de Gobernación; de Relaciones Exteriores; de la Defensa Nacional; de Marina; de Seguridad y Protección Ciudadana; de Hacienda y Crédito Público; de Bienestar; de Medio Ambiente y Recursos Naturales; de Energía; de Economía; de Infraestructura, Comunicaciones y Transportes; de Trabajo y Previsión Social, así como de Turismo y de la Agencia de Transformación Digital y Telecomunicaciones, quienes podrán designar a una persona suplente, la cual deberá ser titular de una Subsecretaría o su equivalente. Asimismo, se podrá invitar a participar en las sesiones de la Comisión a aquellas autoridades y personas representantes de los sectores privado y social que tengan relación con los asuntos a tratar, quienes tendrán voz, pero no voto.</div>
<div> ...</div>
<div> En las sesiones que se vayan a tratar asuntos en materia de seguridad nacional, serán invitadas permanentes las personas titulares de la Fiscalía General de la República, del Centro Nacional de Inteligencia, del Servicio de Administración Tributaria y de la Unidad de Inteligencia Financiera, quienes tendrán voz, pero no voto.</div>
<div> Sin perjuicio de lo anterior, la Comisión podrá sesionar de manera extraordinaria en cualquier momento, a convocatoria de la persona titular de la Presidencia cuando los asuntos así lo requieran. Las sesiones se llevarán a cabo de forma que se garantice el cumplimiento de los plazos previstos en la Ley.</div>','3','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('6612bbc6-7a07-5bf7-ad63-8d43d5ccf1e9','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 27','<div> ARTÍCULO 27.- ...</div>
<div> I.- a III.- ...</div>
<div> IV.-     Presentar al Congreso de la Unión un informe estadístico cuatrimestral sobre el comportamiento de la inversión extranjera en el país, que incluya los sectores económicos y las regiones en las que ésta se ubica;</div>
<div> V.-      Enviar al Congreso de la Unión semestralmente un informe de la gestión de la Comisión en materia de seguridad nacional y, en su caso, comparecer ante las comisiones competentes que la convoquen, y</div>
<div> VI.-     Las demás que le confiera esta Ley, su Reglamento y otras disposiciones legales o administrativas.</div>','4','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('163a16e3-8ea3-530e-b8c9-bdb269d9f3cb','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 28','<div> ARTÍCULO 28.- La Comisión deberá resolver las solicitudes sometidas a su consideración dentro de un plazo que no excederá de cuarenta y cinco días hábiles contado a partir de la fecha de presentación de la solicitud respectiva, en los términos establecidos en el Reglamento de la presente Ley. Cuando los asuntos a tratar se refieran a cuestiones de seguridad nacional, se estará a lo dispuesto en el Título Sexto Bis de esta Ley.</div>
<div> En caso de que la Comisión no resuelva en el plazo señalado, la solicitud se considerará aprobada en los términos presentados. A petición expresa de la persona interesada, la Secretaría deberá expedir la autorización correspondiente. Lo previsto en el presente párrafo no será aplicable en asuntos en materia de seguridad nacional y se deberá estar a lo dispuesto en el Título Sexto Bis de esta Ley.</div>','5','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('484b4038-3421-5147-b56e-3c067e3d1b2b','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 29','<div> ARTÍCULO 29.- ...</div>
<div> I.- y II.- ...</div>
<div> III.-     El cumplimiento de las disposiciones en materia ambiental contenidas en los ordenamientos ecológicos que rigen la materia;</div>
<div> IV.-     En general, la aportación para incrementar la competitividad de la planta productiva del país, y</div>
<div> V.-      La existencia de riesgos o amenazas a la seguridad nacional para los asuntos a que se refiere el Título Sexto Bis de esta Ley.</div>
<div> ...</div>','6','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('b50adb83-ebd7-505e-8d23-badd50ee702f','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 30','<div> ARTÍCULO 30.- (Se deroga)</div>
<div> TITULO SEXTO BIS<br/> </div>
<div> DE LA SEGURIDAD NACIONAL EN LAS INVERSIONES EXTRANJERAS<br/> </div>','7','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('c9c3679d-fee3-5bfd-8126-c030028f6e85','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Capítulo I','<div> Capítulo I<br/> </div>
<div> Inversiones extranjeras sujetas a escrutinio de seguridad nacional<br/> </div>','8','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('c71cd140-5912-5080-adbb-7b0a07d328dc','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 30 BIS','<div> ARTÍCULO 30 BIS.- Por razones de seguridad nacional, se requiere resolución favorable de la Comisión para que la inversión extranjera participe, directa o indirectamente, en un porcentaje mayor al 49% del capital social de una sociedad mexicana, en la que el valor total de sus activos, al momento de someter la solicitud de adquisición, rebase el monto que determine la Comisión mediante resolución general y tenga por actividad económica alguna de las siguientes:</div>
<div> I.-       Infraestructuras estratégicas ya sean físicas o virtuales, en las que se incluyen aquellas vinculadas con el sector energético, transporte, sanidad, comunicaciones, minería, tratamiento o almacenamiento de datos, sistemas digitales, aeroespacial, de defensa e instalaciones sensibles, así como de terrenos e inmuebles que sean indispensables para el uso de dichas infraestructuras;</div>
<div> II.-      Tecnologías críticas y productos de doble uso, incluidas la inteligencia artificial, la robótica, los semiconductores, la ciberseguridad, las tecnologías aeroespaciales, de defensa, de almacenamiento de energía, cuántica y nuclear, así como las nanotecnologías y biotecnologías;</div>
<div> III.-     El suministro de insumos fundamentales, en particular energía o materias primas, así como seguridad alimentaria;</div>
<div> IV.-     El acceso a información sensible, en particular, datos personales, o la capacidad de controlar dicha información, y</div>
<div> V.-      Las demás actividades o sectores económicos análogos o de similar naturaleza que determina la Comisión mediante resolución general.</div>
<div> En el caso de que el valor total de los activos de la sociedad mexicana no supere el umbral a que se refiere este artículo, pero el porcentaje de participación que se pretenda sea superior al 49% del capital social, la presentación de la solicitud ante la Comisión será voluntaria.</div>','9','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('5c9920c3-bb24-5568-88bd-0d5781d0e037','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Capítulo II','<div> Capítulo II<br/> </div>
<div> De la solicitud de autorización y resolución de la Comisión<br/> </div>','10','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('6d6af640-060b-58df-b6d9-fc92e27c339f','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 30 TER','<div> ARTÍCULO 30 TER.- La solicitud de autorización a que se refiere el presente Título, deberá presentarse ante la Secretaría Técnica de la Comisión, de manera conjunta por la sociedad mexicana y el inversionista extranjero, en términos de lo dispuesto en la presente Ley y su Reglamento.</div>','11','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('5fb6f838-b1f3-5b4f-90f1-bac8e9c1c753','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 30 QUATER','<div> ARTÍCULO 30 QUATER.- La Comisión deberá resolver las solicitudes sometidas a su consideración dentro de un plazo de cuarenta y cinco días hábiles contado a partir de la fecha de presentación de la solicitud respectiva, en los términos establecidos en el Reglamento de la presente Ley y, comunicará a las personas interesadas el sentido de dicha resolución, a través de la Secretaría.</div>
<div> A falta de disposición expresa en la presente Ley y su Reglamento, para la atención de las solicitudes, la Comisión se estará a lo dispuesto en la Ley Federal de Procedimiento Administrativo.</div>','12','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('b2754609-0c90-585a-a2f6-6d38a253b037','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 30 QUINQUIES','<div> ARTÍCULO 30 QUINQUIES.- La Comisión resolverá, en cualquiera de los siguientes sentidos:</div>
<div> I.-       Determinar la inexistencia de riesgos o amenazas a la seguridad nacional como resultado de la evaluación realizada y; por tanto, declarar viable la adquisición de la sociedad mexicana por parte de la inversión extranjera;</div>
<div> II.-      Sujetar el proyecto de adquisición de la sociedad mexicana de que se trate por parte de la inversión extranjera a la modificación de dicho proyecto para la mitigación del riesgo, a cargo de las partes involucradas, o</div>
<div> III.-     Impedir la adquisición de la sociedad mexicana por parte de la inversión extranjera por seguridad nacional.</div>
<div> La resolución emitida conforme a las fracciones I y II, incluirá términos y condiciones específicos por cada caso, que podrán implicar el reporte periódico a cargo de las partes involucradas y la evaluación del cumplimiento del orden jurídico nacional.</div>','13','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('ee4c2cdc-ea0f-534b-95af-cc4b5e0b2bca','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 30 SEXIES','<div> ARTÍCULO 30 SEXIES.- Las personas integrantes de la Comisión al tratar asuntos en materia de seguridad nacional no podrán abstenerse de votar en la sesión respectiva, por lo que deberán pronunciarse en sentido favorable o en contra. Los acuerdos en sesiones donde se traten temas de seguridad nacional serán tomados por la mayoría de las personas integrantes de la Comisión.</div>','14','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('1ab2be8c-60f2-551f-8a6d-0ec560f56c7e','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Artículo 38','<div> ARTÍCULO 38.- ...</div>
<div> I.-       En caso de que la inversión extranjera lleve a cabo actividades, adquisiciones o cualquier otro acto que para su realización requiera resolución favorable de la Comisión, sin que ésta se haya obtenido previamente, conforme a los artículos 8o. y 9o. de esta Ley, se impondrá multa de mil a cinco mil veces el valor diario de la Unidad de Medida y Actualización;</div>
<div> II.-      En caso de que personas morales extranjeras realicen habitualmente actos de comercio en la República Mexicana, sin haber obtenido previamente la autorización de la Secretaría, se impondrá multa de quinientos a mil veces el valor diario de la Unidad de Medida y Actualización;</div>
<div> III.-     En caso de realizar actos en contravención a lo establecido en esta Ley o en sus disposiciones reglamentarias en materia de inversión neutra, se impondrá multas de cien a trescientas veces el valor diario de la Unidad de Medida y Actualización;</div>
<div> IV.-     En caso de omisión, cumplimiento extemporáneo, presentación de información incompleta o incorrecta respecto de las obligaciones de inscripción, reporte o aviso al Registro por parte de los sujetos obligados, se impondrá multa de treinta a cien veces el valor diario de la Unidad de Medida y Actualización;</div>
<div> V.-      En caso de simulación de actos con el propósito de permitir el goce o la disposición de bienes inmuebles en la zona restringida a personas físicas o morales extranjeras o a sociedades mexicanas que no tengan cláusula de exclusión de extranjeros, en contravención a lo dispuesto por los Títulos Segundo y Tercero de esta Ley, se sancionará al infractor con multa hasta por el importe de la operación;</div>
<div> VI.-     En caso de que la sociedad mexicana transmita, ceda, entregue o transfiera la participación accionaria al inversionista extranjero, a pesar de haber recibido la denegación de autorización de la adquisición por parte de la Comisión o sin haber obtenido una resolución favorable de la Comisión previamente, en términos del Título Sexto Bis de esta Ley, se impondrá una multa de cinco mil a doscientas mil veces el valor diario de la Unidad de Medida y Actualización;</div>
<div> VII.-    En caso de incumplimiento a las acciones de mitigación del riesgo dispuestas por la Comisión, en términos del Título Sexto Bis de esta Ley, se impondrá una multa de cinco mil a doscientas mil veces el valor diario de la Unidad de Medida y Actualización, y</div>
<div> VIII.-   En caso de las demás infracciones a esta Ley o a sus disposiciones reglamentarias, se impondrá multa de cien a mil veces el valor diario de la Unidad de Medida y Actualización.</div>
<div> Además de las sanciones previstas en el párrafo anterior, la Comisión podrá determinar la acción de desinversión, sometida al procedimiento que así se determine.</div>
<div> La Comisión otorgará un plazo de noventa días hábiles, contado a partir del día siguiente de la notificación de la sanción a que se refiere el párrafo anterior, prorrogables por un periodo igual, para que la persona inversionista extranjera desincorpore los activos adquiridos a una empresa.</div>
<div> Se deroga</div>
<div> ...</div>
<div> ...</div>
<div> ...</div>','15','ordinario');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('1c9c3578-5c99-54c7-8c6c-623e70ef02fb','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Disposiciones transitorias','<div> Transitorios<br/> </div>','16','transitorio');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('afb989fb-247b-5302-8699-cb6288c109b0','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Transitorio Primero','<div> Primero. El presente Decreto entrará en vigor el día siguiente al de su publicación en el Diario Oficial de la Federación.</div>','17','transitorio');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('126a9b6a-5175-564b-a030-f1c645891ebd','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Transitorio Segundo','<div> Segundo. La resolución general mediante la cual la Comisión Nacional de Inversiones Extranjeras establezca el monto previsto en el artículo 30 BIS de la Ley de Inversión Extranjera, deberá ser emitida y publicada en el Diario Oficial de la Federación, en un plazo no mayor a ciento ochenta días naturales contado a partir del día siguiente a aquel en el que se publique en el Diario Oficial de la Federación el presente Decreto.</div>','18','transitorio');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('73c910f4-d2be-5b6f-91e5-8559a52e654a','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Transitorio Tercero','<div> Tercero. Las erogaciones que, en su caso, se generen con motivo de la entrada en vigor del presente Decreto, se cubrirán mediante movimientos compensados, conforme a las disposiciones jurídicas aplicables con cargo al presupuesto aprobado para la Secretaría de Economía para el ejercicio fiscal correspondiente, por lo que no se autorizarán ampliaciones al presupuesto de ésta para tales fines.</div>','19','transitorio');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('323dd2dc-8396-582e-8096-d48067d36d7c','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Transitorio Cuarto','<div> Cuarto. Los asuntos que se encuentren en trámite antes de la entrada en vigor del presente Decreto, se atenderán conforme a las disposiciones que se encontraban vigentes al momento de su presentación.</div>
<div> Ciudad de México, a 27 de octubre de 2026.- Sen. Higinio Martínez Miranda, Presidente.- Dip. Raúl Bolaños-Cacho Cué, Presidente.- Sen. María Martina Kantún Can, Secretaria.- Dip. Francisco Amadeo Espinosa Ramos, Secretario.- Rúbricas."</div>
<div> En cumplimiento de lo dispuesto por la fracción I del Artículo 89 de la Constitución Política de los Estados Unidos Mexicanos, y para su debida publicación y observancia, expido el presente Decreto en la Residencia del Poder Ejecutivo Federal, en la Ciudad de México, a 13 de noviembre de 2026.- Claudia Sheinbaum Pardo, Presidenta de los Estados Unidos Mexicanos.- Rúbrica.- Lcda. Rosa Icela Rodríguez Velázquez, Secretaria de Gobernación.- Rúbrica.</div>','20','transitorio');
INSERT INTO public.articulos (id,ley_id,identificador,contenido,orden,tipo_articulo) VALUES ('86d7efaf-900c-56ae-a3bf-fa8d95cd13ab','33120acd-fa2a-5ee0-a2b5-7bfda197ed07','Nota editorial · Ley de origen','<p><a href="#ley-ecad609a-fdcb-5d6d-8de4-2bbb31a70d73">Texto original · Ley de Inversión Extranjera</a></p>','21','complementario');
COMMIT;
